#!/usr/bin/env bash
# normalize-c.sh <file.c>  -> normalized C on stdout, used by regen-diff.sh.
# Removes the noise between the old Squeak VMMaker.oscog output (checked-in
# plugins/*/src/common/*.c) and this tree's Pharo Slang output:
#   - the 'Automatically generated by ...' header comment and __buildInfo line
#   - 'VMMaker.oscog-eem.NNNN ' inside moduleName strings
#   - Pharo Slang's '_' prefix on locals/arguments (_anOop -> anOop)
#   - comments after #endif / #else, trailing whitespace, blank lines
#   - '(usqInt) x' vs '((usqInt) x)' style casts are NOT normalized (real diffs)
set -u
f="$1"
awk '
  NR==1 && /^\/\* Automatically generated/ { if ($0 ~ /\*\//) next; skip=1; next }
  skip { if ($0 ~ /\*\//) skip=0; next }
  /^static char __buildInfo\[\]/ { next }
  { print }
' "$f" \
| sed -E \
    -e 's/ VMMaker\.oscog-[a-z]+\.[0-9]+//g' \
    -e 's/(^|[^A-Za-z0-9_])_([A-Za-z][A-Za-z0-9_]*)/\1\2/g' \
    -e 's/^(#[ ]*(endif|else))[ \t]*\/\*.*\*\/[ \t]*$/\1/' \
    -e 's/[ \t]+$//' \
| grep -v '^[[:space:]]*$'
